  "python": "def pilot_policy(trace):
    if not trace:
        return None
    last_action, last_label = trace[-1]
    action_name = last_action.name
    args = json.loads(last_action.arguments)
    label_categories = last_label.subset
    slot_policies = {
        "slot:archive": {"UNVERIFIED"},
        "slot:counsel": {"UNVERIFIED"},
        "slot:public": {"PERSONAL", "EMBARGOED", "LICENSED"},
        "slot:syndicate": {"PERSONAL", "EMBARGOED"},
        "slot:wire": {"PERSONAL", "LICENSED"}
    }
    if action_name in ["research/collect_material", "editor/edit_draft", "publisher/review_release"]:
        return None
    elif action_name in ["legal/publish", "editorial/publish"]:
        audience = args.get("audience")
        record = args.get("record")
        if action_name == "editorial/publish":
            audience_slot_map = {"staff": "slot:newsroom", "partner": "slot:syndicate", "release": "slot:public"}
        else:
            audience_slot_map = {"staff": "slot:newsroom", "partner": "slot:counsel", "release": "slot:wire"}
        audience_slot = audience_slot_map.get(audience)
        additional_slot = None
        if record == "archive":
            additional_slot = "slot:archive"
        elif record == "partner":
            additional_slot = "slot:partner"
        elif record == "public":
            additional_slot = "slot:public"
        dest_slots = [audience_slot]
        if additional_slot is not None:
            dest_slots.append(additional_slot)
        if len(dest_slots) > 0 and dest_slots[0] in slot_policies:
            if not label_categories.issubset(slot_policies[dest_slots[0]]):
                raise PolicyViolation("Category not allowed in destination slot")
        if len(dest_slots) > 1 and dest_slots[1] in slot_policies:
            if not label_categories.issubset(slot_policies[dest_slots[1]]):
                raise PolicyViolation("Category not allowed in destination slot")
        return None
    else:
        raise PolicyViolation("Unknown action")"
